use super::*;
use crate::player::PlaybackSource;use rodio::Source;
struct Fixture{root:PathBuf,catalog:Option<CatalogState>,ids:Vec<String>}
impl Fixture{
 fn new()->Self{let root=std::env::temp_dir().join(format!("sw-foundation-{}",Uuid::new_v4()));fs::create_dir(&root).unwrap();let root=fs::canonicalize(root).unwrap();let catalog=CatalogState::new(root.join("catalog.sqlite")).unwrap();let mut ids=vec![];for name in ["a.wav","b.wav"]{let path=root.join(name);fs::copy(Path::new(env!("CARGO_MANIFEST_DIR")).join("../build/s1-samples/pcm-44100.wav"),&path).unwrap();let (size,modified)=identity(&path).unwrap();let id=Uuid::new_v4().to_string();let conn=rusqlite::Connection::open(catalog.database_path()).unwrap();conn.execute("INSERT INTO assets(id,path_key,path,name,format,size,modified,rate,channels,duration,status) VALUES(?1,?2,?2,?3,'WAV',?4,?5,44100,1,0.5,'ready')",rusqlite::params![id,path.to_string_lossy(),name,size,modified]).unwrap();conn.execute("INSERT INTO asset_libraries VALUES(?1,'sound')",[&id]).unwrap();ids.push(id);}Self{root,catalog:Some(catalog),ids}}
 fn catalog(&self)->&CatalogState{self.catalog.as_ref().unwrap()}
 fn folder(&self,name:&str)->PathBuf{let p=self.root.join(name);fs::create_dir(&p).unwrap();p}
}
impl Drop for Fixture{fn drop(&mut self){self.catalog.take();let _=fs::remove_dir_all(&self.root);}}
#[test]fn duplicates_cache_respects_identity_and_library_without_source_changes(){let f=Fixture::new();let groups=duplicate_groups(f.catalog(),vec![],"sound",&f.root.join("hashes"),&AtomicBool::new(false),|_,_|{}).unwrap();assert_eq!(groups.len(),1);assert_eq!(groups[0]["count"],2);assert!(duplicate_groups(f.catalog(),vec![],"music",&f.root.join("hashes"),&AtomicBool::new(false),|_,_|{}).unwrap().is_empty());let path=f.catalog().resolve_asset(&f.ids[1]).unwrap();let mut bytes=fs::read(&path).unwrap();bytes[44]^=1;fs::write(&path,bytes).unwrap();assert!(duplicate_groups(f.catalog(),vec![],"sound",&f.root.join("hashes"),&AtomicBool::new(false),|_,_|{}).is_err());}
#[test]fn batch_copy_is_exact_no_overwrite_and_cancel_keeps_existing(){let f=Fixture::new();let out=f.folder("out");let original=fs::read(f.catalog().resolve_asset(&f.ids[0]).unwrap()).unwrap();let first=export_batch(f.catalog(),f.ids.clone(),"sound","batch_export",out.to_str().unwrap(),48000,1.0,&AtomicBool::new(false),|_,_|{}).unwrap();assert_eq!(first.len(),2);assert_eq!(fs::read(out.join("a.wav")).unwrap(),original);assert!(export_batch(f.catalog(),f.ids.clone(),"sound","batch_export",out.to_str().unwrap(),48000,1.0,&AtomicBool::new(false),|_,_|{}).is_err());assert_eq!(fs::read(out.join("a.wav")).unwrap(),original);let cancel=AtomicBool::new(false);let fresh=f.folder("fresh");assert!(export_batch(f.catalog(),f.ids.clone(),"sound","batch_export",fresh.to_str().unwrap(),48000,1.0,&cancel,|_,_|cancel.store(true,Ordering::Release)).is_err());assert_eq!(fs::read_dir(fresh).unwrap().count(),0);assert_eq!(fs::read(f.catalog().resolve_asset(&f.ids[0]).unwrap()).unwrap(),original);}
#[test]fn plugin_scan_is_discovery_only_and_does_not_load_libraries(){let f=Fixture::new();let folder=f.folder("plugins");fs::create_dir(folder.join("Example.vst3")).unwrap();fs::write(folder.join("candidate.dll"),b"not executable code").unwrap();let items=plugins(folder.to_str().unwrap(),&AtomicBool::new(false)).unwrap();assert_eq!(items.len(),2);assert!(items.iter().all(|item|item["validated"]==false));assert_eq!(fs::read(folder.join("candidate.dll")).unwrap(),b"not executable code");}
#[test]#[ignore="需显式提供本机FFmpeg/SoXR，合成样本真实转换"]fn ffmpeg_resample_and_preserved_pitch_are_real(){let f=Fixture::new();let out=f.folder("convert");let original=fs::read(f.catalog().resolve_asset(&f.ids[0]).unwrap()).unwrap();let result=export_batch(f.catalog(),vec![f.ids[0].clone()],"sound","resample",out.to_str().unwrap(),48000,1.0,&AtomicBool::new(false),|_,_|{}).unwrap();let path=PathBuf::from(result[0]["path"].as_str().unwrap());let source=PlaybackSource::open(&path).unwrap();assert_eq!(source.sample_rate(),48000);assert_eq!(source.channels(),1);assert!((source.total_duration().unwrap().as_secs_f64()-0.5).abs()<0.01);let result=export_batch(f.catalog(),vec![f.ids[1].clone()],"sound","stretch",out.to_str().unwrap(),48000,0.5,&AtomicBool::new(false),|_,_|{}).unwrap();let path=PathBuf::from(result[0]["path"].as_str().unwrap());let mut source=PlaybackSource::open(&path).unwrap();let rate=source.sample_rate() as f64;let duration=source.total_duration().unwrap().as_secs_f64();assert!((duration-1.0).abs()<0.08,"duration {duration}");let values:Vec<f32>=source.by_ref().collect();let crossings=values.windows(2).filter(|p|p[0]<=0.0&&p[1]>0.0).count() as f64;let pitch=crossings/(values.len() as f64/rate);assert!((pitch-440.0).abs()<20.0,"pitch {pitch}");assert_eq!(fs::read(f.catalog().resolve_asset(&f.ids[0]).unwrap()).unwrap(),original);}
fn pcm_wav(samples:&[i16])->Vec<u8>{let mut b=Vec::new();let len=(samples.len()*2) as u32;b.extend(b"RIFF");b.extend((36+len).to_le_bytes());b.extend(b"WAVEfmt ");b.extend(16u32.to_le_bytes());b.extend(1u16.to_le_bytes());b.extend(1u16.to_le_bytes());b.extend(44100u32.to_le_bytes());b.extend(88200u32.to_le_bytes());b.extend(2u16.to_le_bytes());b.extend(16u16.to_le_bytes());b.extend(b"data");b.extend(len.to_le_bytes());for s in samples{b.extend(s.to_le_bytes());}b}
fn pcm_aiff(samples:&[i16])->Vec<u8>{let mut b=Vec::new();let ssnd=8+(samples.len()*2) as u32;b.extend(b"FORM");b.extend((4+8+18+8+ssnd).to_be_bytes());b.extend(b"AIFF");b.extend(b"COMM");b.extend(18u32.to_be_bytes());b.extend(1u16.to_be_bytes());b.extend((samples.len() as u32).to_be_bytes());b.extend(16u16.to_be_bytes());b.extend([0x40,0x0E,0xAC,0x44,0,0,0,0,0,0]);b.extend(b"SSND");b.extend(ssnd.to_be_bytes());b.extend(0u32.to_be_bytes());b.extend(0u32.to_be_bytes());for s in samples{b.extend(s.to_be_bytes());}b}
fn insert_asset(f:&Fixture,name:&str,bytes:&[u8],format:&str,duration:f64)->String{let path=f.root.join(name);fs::write(&path,bytes).unwrap();let (size,modified)=identity(&path).unwrap();let id=Uuid::new_v4().to_string();let conn=rusqlite::Connection::open(f.catalog().database_path()).unwrap();conn.execute("INSERT INTO assets(id,path_key,path,name,format,size,modified,rate,channels,duration,status) VALUES(?1,?2,?2,?3,?4,?5,?6,44100,1,?7,'ready')",rusqlite::params![id,path.to_string_lossy(),name,format,size,modified,duration]).unwrap();conn.execute("INSERT INTO asset_libraries VALUES(?1,'sound')",[&id]).unwrap();id}
#[test]fn wave_duplicates_group_identical_waveforms_across_containers_and_keep_sources(){
 let f=Fixture::new();let samples:[i16;8]=[0,1000,-1000,2000,-2000,3000,-3000,4000];
 let wav=pcm_wav(&samples);let aiff=pcm_aiff(&samples);let mut different=wav.clone();*different.last_mut().unwrap()^=1;
 let duration=8.0/44100.0;
 let w1=insert_asset(&f,"w1.wav",&wav,"WAV",duration);let w2=insert_asset(&f,"w2.wav",&wav,"WAV",duration);
 let a1=insert_asset(&f,"a1.aiff",&aiff,"AIFF",duration);let d1=insert_asset(&f,"d1.wav",&different,"WAV",duration);
 let e1=insert_asset(&f,"e1.wav",&wav,"WAV",0.6);
 let hashes=f.root.join("wave-hashes");
 let groups=wave_duplicate_groups(f.catalog(),vec![],"sound",&hashes,&AtomicBool::new(false),|_,_|{}).unwrap();
 // Fixture 的 a/b 字节相同自成一组；w1/w2/a1 跨容器波形一致成一组；d1 同声长不同波形、e1 同时长键不同，均不入组。
 assert_eq!(groups.len(),2);
 let mine=groups.iter().find(|g|g["ids"].as_array().unwrap().contains(&json!(a1))).unwrap();
 assert_eq!(mine["count"],3);assert_eq!(mine["wave"],true);
 let ids=mine["ids"].as_array().unwrap();
 assert!(ids.contains(&json!(w1))&&ids.contains(&json!(w2)));assert!(!ids.contains(&json!(d1))&&!ids.contains(&json!(e1)));
 assert_eq!(fs::read(f.root.join("a1.aiff")).unwrap(),aiff);assert_eq!(fs::read(f.root.join("w1.wav")).unwrap(),wav);
 // 缓存命中路径结果一致；音乐库无归属不成组；源文件被改动则整批拒绝。
 let again=wave_duplicate_groups(f.catalog(),vec![],"sound",&hashes,&AtomicBool::new(false),|_,_|{}).unwrap();assert_eq!(again.len(),2);
 assert!(wave_duplicate_groups(f.catalog(),vec![],"music",&hashes,&AtomicBool::new(false),|_,_|{}).unwrap().is_empty());
 let path=f.catalog().resolve_asset(&a1).unwrap();let mut bytes=fs::read(&path).unwrap();bytes[10]^=1;fs::write(&path,bytes).unwrap();
 assert!(wave_duplicate_groups(f.catalog(),vec![],"sound",&hashes,&AtomicBool::new(false),|_,_|{}).is_err());
}
